// Stackbound offline play. On install every file the game needs goes into a cache, and from then on the game
// loads from that cache first, so it starts with no connection. Each build writes a new VERSION (from the files'
// contents), which installs a fresh cache and drops the old one. Generated by the build: do not edit by hand.
'use strict';
const VERSION = 'sb-ee3fc33dc14f';
const FILES = ["./", "index.html", "Play%20Stackbound.html", "manifest.webmanifest", "css/dating.css", "css/style.css", "css/fonts/AlfaSlabOne.woff2", "css/fonts/Caveat.woff2", "css/fonts/Fredoka.woff2", "css/fonts/Kreon.woff2", "css/fonts/Nunito.woff2", "js/achieve.js", "js/core.js", "js/cosmetics.js", "js/data.js", "js/dating-art.js", "js/dating-story.js", "js/dating.js", "js/emblems.js", "js/engine.js", "js/flutter.js", "js/fx.js", "js/iconart.js", "js/icons.js", "js/logo.js", "js/looks.js", "js/music.js", "js/render.js", "js/rival.js", "js/run.js", "js/score.js", "js/sfx.js", "js/skins.js", "js/sweet.js", "js/touch.js", "js/tutorial.js", "js/ui.js", "icons/apple-touch-icon.png", "icons/favicon-32.png", "icons/icon-192.png", "icons/icon-512.png", "icons/icon-maskable-512.png"];
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(VERSION).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('sb-') && k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(caches.open(VERSION).then((c) => c.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res.ok) c.put(req, res.clone());
    return res;
  }).catch(() => (req.mode === 'navigate' ? c.match('Play%20Stackbound.html') : Response.error())))));
});
